            if g[r][c] == 1 and any(9 in row for row in grid):
                g[r][c] = 0
    # Fill only gaps whose two horizontal neighbours are container walls.
    for r in range(h):
        for c in range(1, w - 1):
            if g[r][c] == 0 and g[r][c-1] == g[r][c+1] and g[r][c-1] not in (0, 1, 9):
                g[r][c] = 1
    return g
